// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address actor, address newOwner) public {
        // Hand ownership to the fuzzed actor: initial owner is address(0)
        vm.prank(address(0));
        c.transferOwnership(actor);

        // The owner can always transfer ownership to any address
        vm.prank(actor);
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok && c.owner() == newOwner);
    }
}
